package com.example.paymentservicefeb25.outbox;
import org.slf4j.*; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class OutboxPublisher { private static final Logger log=LoggerFactory.getLogger(OutboxPublisher.class); private final OutboxEventRepository repo; private final KafkaTemplate<String,String> kafka; public OutboxPublisher(OutboxEventRepository repo,KafkaTemplate<String,String> kafka){this.repo=repo;this.kafka=kafka;} @Scheduled(fixedDelayString="${kafka.outbox.publish-interval-ms:5000}") @Transactional public void publish(){ for(OutboxEvent e:repo.findTop50ByPublishedAtIsNullOrderByCreatedAtAsc()){ try{kafka.send(e.getTopic(),e.getEventKey(),e.getPayload()).get();e.setPublishedAt(java.time.Instant.now());repo.save(e);}catch(Exception ex){log.error("Payment outbox publish failed eventId={}",e.getEventId(),ex);} } } }
